def process(detection_packet, metadata, state={}):
    import numpy as np
    from scipy.optimize import linear_sum_assignment
    if detection_packet['frame_index'] != metadata['frame_index']:
        raise ValueError('Person detections and metadata belong to different frames')
    tracks = state.setdefault('tracks', [])
    next_id = state.setdefault('next_id', 1)
    detections = detection_packet['detections']
    def iou(a, b):
        ax1, ay1, ax2, ay2 = a; bx1, by1, bx2, by2 = b
        inter = max(0, min(ax2, bx2) - max(ax1, bx1)) * max(0, min(ay2, by2) - max(ay1, by1))
        area_a = max(0, ax2 - ax1) * max(0, ay2 - ay1)
        area_b = max(0, bx2 - bx1) * max(0, by2 - by1)
        union = area_a + area_b - inter
        return inter / union if union > 0 else 0.0
    def center(box):
        x1, y1, x2, y2 = box
        return (int((x1 + x2) / 2), int((y1 + y2) / 2))
    if tracks and detections:
        cost = np.zeros((len(tracks), len(detections)))
        for i, track in enumerate(tracks):
            for j, det in enumerate(detections):
                cost[i, j] = 1 - iou(track['box'], det['box'])
        rows, cols = linear_sum_assignment(cost)
    else:
        rows, cols = [], []
    matched_tracks, matched_dets = set(), set()
    for row, col in zip(rows, cols):
        if 1 - cost[row, col] >= state.get('iou_threshold', 0.3):
            track = tracks[row]; det = detections[col]
            track['box'] = det['box']; track['score'] = det['score']
            track['hits'] += 1; track['misses'] = 0
            track['trail'].append(center(det['box']))
            track['trail'] = track['trail'][-state.get('trail_length', 30):]
            matched_tracks.add(row); matched_dets.add(col)
    for i, track in enumerate(tracks):
        if i not in matched_tracks:
            track['misses'] += 1
    for j, det in enumerate(detections):
        if j not in matched_dets:
            tracks.append({'id': next_id, 'box': det['box'], 'score': det['score'], 'misses': 0, 'hits': 1, 'trail': [center(det['box'])]})
            next_id += 1
    tracks[:] = [track for track in tracks if track['misses'] <= state.get('max_age', 15)]
    state['next_id'] = next_id
    active = [dict(track) for track in tracks if track['misses'] == 0]
    return {'frame_index': metadata['frame_index'], 'timestamp_s': metadata['timestamp_s'], 'fps': metadata['fps'], 'width': metadata['width'], 'height': metadata['height'], 'tracks': active, 'current_people': len(active), 'unique_people': next_id - 1}

def process(packet, state={}):
    polygon = state.get('polygon', [[256, 432], [1280, 432], [1280, 1152], [256, 1152]])
    records = state.setdefault('records', {})
    def cross(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    def on_segment(a, b, c):
        return abs(cross(a, b, c)) <= 1e-9 and min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= c[1] <= max(a[1], b[1])
    def segments_intersect(a, b, c, d):
        ab_c, ab_d, cd_a, cd_b = cross(a, b, c), cross(a, b, d), cross(c, d, a), cross(c, d, b)
        return ((ab_c > 0 and ab_d < 0 or ab_c < 0 and ab_d > 0) and (cd_a > 0 and cd_b < 0 or cd_a < 0 and cd_b > 0)) or on_segment(a, b, c) or on_segment(a, b, d) or on_segment(c, d, a) or on_segment(c, d, b)
    def point_in_polygon(pt):
        inside = False
        for i in range(len(polygon)):
            a, b = polygon[i], polygon[(i + 1) % len(polygon)]
            if on_segment(a, b, pt):
                return True
            if (a[1] > pt[1]) != (b[1] > pt[1]):
                crossing_x = a[0] + (pt[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
                if crossing_x > pt[0]:
                    inside = not inside
        return inside
    def overlaps(box):
        x1, y1, x2, y2 = box
        if x2 < x1 or y2 < y1:
            return False
        corners = [(x1, y1), (x2, y1), (x2, y2), (x1, y2)]
        if any(point_in_polygon(p) for p in corners):
            return True
        if any(x1 <= p[0] <= x2 and y1 <= p[1] <= y2 for p in polygon):
            return True
        return any(segments_intersect(corners[i], corners[(i + 1) % 4], polygon[j], polygon[(j + 1) % len(polygon)]) for i in range(4) for j in range(len(polygon)))
    enriched, events = [], []
    for track in packet['tracks']:
        inside = overlaps(track['box'])
        record = records.setdefault(track['id'], {'frames_in_zone': 0, 'ever_inside': False})
        if inside:
            record['frames_in_zone'] += 1
            record['ever_inside'] = True
            events.append({'type': 'hazard_zone', 'track_id': track['id'], 'box': track['box'], 'status': 'inside', 'polygon': polygon})
        item = dict(track)
        item['inside_hazard_zone'] = inside
        item['zone_dwell_s'] = record['frames_in_zone'] / packet['fps']
        enriched.append(item)
    result = dict(packet)
    result['tracks'] = enriched
    result['hazard_polygon'] = polygon
    result['current_in_zone'] = len(events)
    result['unique_people_ever_in_zone'] = sum(record['ever_inside'] for record in records.values())
    result['events'] = events
    return result

def process(status, ppe_packet, parameters=None):
    if parameters is None:
        parameters = {'helmet_region_height_fraction': 0.4, 'vest_region_top_fraction': 0.25, 'vest_region_bottom_fraction': 0.8, 'rules': [{'condition': 'any missing', 'items': ['hard hat', 'safety vest'], 'name': 'alert on missing required PPE'}]}
    if status['frame_index'] != ppe_packet['frame_index']:
        raise ValueError('PPE detections and tracked people belong to different frames')
    tracks = [dict(track) for track in status['tracks']]
    matches = {track['id']: {'helmet': [], 'Vest': []} for track in tracks}
    for item in ppe_packet['detections']:
        label = item['class']
        if label not in ('helmet', 'Vest'):
            continue
        x1, y1, x2, y2 = item['box']
        cx, cy = (x1 + x2) / 2, (y1 + y2) / 2
        candidates = []
        for track in tracks:
            px1, py1, px2, py2 = track['box']
            height = py2 - py1
            width = px2 - px1
            if width <= 0 or height <= 0:
                continue
            if label == 'helmet':
                top, bottom = py1, py1 + parameters['helmet_region_height_fraction'] * height
            else:
                top = py1 + parameters['vest_region_top_fraction'] * height
                bottom = py1 + parameters['vest_region_bottom_fraction'] * height
            if px1 <= cx <= px2 and top <= cy <= bottom:
                distance = abs(cx - (px1 + px2) / 2) / width + abs(cy - (top + bottom) / 2) / height
                candidates.append((distance, track['id']))
        if candidates:
            _, track_id = min(candidates)
            matches[track_id][label].append(item)
    events = list(status['events'])
    for track in tracks:
        found = matches[track['id']]
        missing = []
        if not found['helmet']:
            missing.append('hard hat')
        if not found['Vest']:
            missing.append('safety vest')
        track['detected_helmet'] = bool(found['helmet'])
        track['detected_vest'] = bool(found['Vest'])
        track['possible_missing_ppe'] = missing
        if missing:
            events.append({'type': 'possible_ppe_violation', 'track_id': track['id'], 'box': track['box'], 'possible_missing': missing, 'certainty': 'unconfirmed', 'reason': 'No matching helmet or vest detection in the expected person region; absence is not established.'})
    result = dict(status)
    result['tracks'] = tracks
    result['ppe_detections'] = ppe_packet['detections']
    result['current_possible_ppe_violations'] = sum(bool(track['possible_missing_ppe']) for track in tracks)
    result['events'] = events
    return result

def process(result, state={}):
    import json
    import paho.mqtt.client as mqtt
    if 'client' not in state:
        client = mqtt.Client()
        client.connect('localhost', 1883, 60)
        client.loop_start()
        state['client'] = client
    for event in result['events']:
        payload = {'frame_index': result['frame_index'], 'timestamp_s': result['timestamp_s'], 'event': event, 'current_people': result['current_people']}
        state['client'].publish('pipegen/person-safety/input1', json.dumps(payload), qos=0)
    return None
